//! 🧪️ The native bounded flood consumes the same region corpus and quotes every retained phase.
use super::*;
const GRANT:RetainedCloneGrant=RetainedCloneGrant{maximum_items:32,maximum_copy_bytes:32768,maximum_capacity_bytes:16777216,maximum_release_bytes:1048576,maximum_depth:4096};
fn close_bound(cursor:&FloodRegionCursor)->usize{16*(3*cursor.page_count()+3)+16}
fn close(cursor:&mut FloodRegionCursor){let bound=close_bound(cursor);cursor.begin_close();for _ in 0..bound{if cursor.terminal_is_empty(){assert_eq!(cursor.workspace_bytes(),0);return}let demand=cursor.close_demands(GRANT.maximum_copy_bytes).unwrap();assert!(demand.copy_bytes<=GRANT.maximum_copy_bytes&&demand.release_bytes<=GRANT.maximum_release_bytes);let step=cursor.close_step(GRANT);assert!(step.work>0,"a fully funded close must advance");let progress=step.result.unwrap().progress();assert!(progress.fits(GRANT));assert!(progress.copied_bytes<=demand.copy_bytes&&progress.retained_capacity_bytes<=demand.capacity_bytes&&progress.released_bytes<=demand.release_bytes);}panic!("flood did not retire within its page/backing-derived bound")}

#[test]
fn neutral_bounded_region_cases_match_shared_graph_oracle(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let budget=fixture["maximumWork"].as_u64().unwrap()as usize;
 for row in fixture["cases"].as_array().unwrap(){let width=row["width"].as_u64().unwrap()as u32;let height=row["height"].as_u64().unwrap()as u32;let pixels:Vec<u8>=row["rows"].as_array().unwrap().iter().flat_map(|line|line.as_str().unwrap().chars().flat_map(|symbol|row["palette"][symbol.to_string()].as_array().unwrap().iter().map(|channel|channel.as_u64().unwrap()as u8).collect::<Vec<_>>())).collect();let seed=if let Some(seed)=row["seed"].as_array(){[seed[0].as_u64().unwrap()as u32,seed[1].as_u64().unwrap()as u32]}else{[(row["seedUv"][0].as_f64().unwrap()*f64::from(width-1)).round()as u32,((1.0-row["seedUv"][1].as_f64().unwrap())*f64::from(height-1)).round()as u32]};let mut cursor=FloodRegionCursor::new(width,height,seed[0],seed[1]).unwrap();let mut work=0;
  for _ in 0..4096{if cursor.done(){break}assert!(cursor.result().is_err());let demand=cursor.demands(budget).unwrap();assert!(demand.copy_bytes<=GRANT.maximum_copy_bytes&&demand.capacity_bytes<=GRANT.maximum_capacity_bytes);let step=cursor.advance(FloodSource::Rgba(&pixels),budget,GRANT,false).result.unwrap();assert!(step.work<=budget as u64);assert!(step.progress.fits(GRANT));assert!(step.progress.copied_bytes<=demand.copy_bytes&&step.progress.retained_capacity_bytes<=demand.capacity_bytes);work+=step.work;}
  let actual:Vec<usize>=cursor.result().unwrap().iter().enumerate().filter_map(|(index,value)|(*value!=0).then_some(index)).collect();assert_eq!(serde_json::to_value(actual).unwrap(),row["expected"]["reached"]);assert!(work>=u64::from(width)*u64::from(height));close(&mut cursor);
 }
}
#[test]
fn uniform_large_region_yields_and_cancel_preserves_workspace_for_close(){let mut cursor=FloodRegionCursor::new(256,256,0,0).unwrap();let mut turns=0;while !cursor.done(){let demand=cursor.demands(256).unwrap();let step=cursor.advance(FloodSource::Uniform([255;4]),256,GRANT,false).result.unwrap();assert!(step.work<=256&&step.progress.fits(GRANT));assert!(step.progress.copied_bytes<=demand.copy_bytes&&step.progress.retained_capacity_bytes<=demand.capacity_bytes);turns+=1;}assert!(turns>=256);assert!(cursor.result().unwrap().iter().all(|value|*value==255));close(&mut cursor);let mut cancelled=FloodRegionCursor::new(256,256,0,0).unwrap();while cancelled.advance(FloodSource::Uniform([255;4]),256,GRANT,false).result.unwrap().completed<=256*256{}assert_eq!(cancelled.advance(FloodSource::Uniform([255;4]),256,GRANT,true).result.unwrap_err().kind,ValueRefusalKind::Canceled);assert!(cancelled.result().is_err());assert!(!cancelled.terminal_is_empty());close(&mut cancelled);}

#[test]
fn denied_grants_do_not_allocate_and_each_allocation_failure_retains_paid_workspace(){
 use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
 let mut cursor=FloodRegionCursor::new(67,63,0,0).unwrap();assert_eq!(cursor.workspace_bytes(),0);let source=FloodSource::Uniform([255;4]);let initial=cursor.demands(3).unwrap();
 for denied in[RetainedCloneGrant{maximum_items:0,..GRANT},RetainedCloneGrant{maximum_copy_bytes:0,..GRANT},RetainedCloneGrant{maximum_capacity_bytes:0,..GRANT},RetainedCloneGrant{maximum_depth:0,..GRANT}]{let(turn,heap)=observe(||cursor.advance(source,3,denied,false));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress,RetainedCloneProgress::default());assert_eq!(cursor.demands(3).unwrap(),initial);assert!(cursor.terminal_is_empty());assert_eq!(cursor.workspace_bytes(),0);}
 for _ in 0..3+3*cursor.page_count(){let((turn,attempts),heap)=observe(||refuse(||cursor.advance(source,3,GRANT,false)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let failure=turn.result.unwrap_err();assert_eq!(failure.kind,ValueRefusalKind::AllocationFailed);assert_eq!(failure.retained_progress().retained_capacity_bytes,0);let(turn,heap)=observe(||cursor.advance(source,3,GRANT,false));let step=turn.result.unwrap();assert_eq!(heap,(step.progress.retained_capacity_bytes,0));assert_eq!(turn.work,1);}
 let bound=close_bound(&cursor);cursor.begin_close();for _ in 0..bound{if cursor.terminal_is_empty(){break;}let demand=cursor.close_demands(GRANT.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..GRANT},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..GRANT},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..GRANT},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..GRANT},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..GRANT}]{if denied.maximum_items!=0&&retained_clone_grant_admits(denied,demand){continue;}let(turn,heap)=observe(||cursor.close_step(denied));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(cursor.close_demands(GRANT.maximum_copy_bytes).unwrap(),demand);}
 let(turn,heap)=observe(||cursor.close_step(GRANT));let progress=turn.result.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));}assert!(cursor.terminal_is_empty());
}

#[test]
fn borrowed_source_identity_accepts_same_range_and_refuses_copy_or_offset_atomically(){
 use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
 let backing=vec![255;8*8*4+4];let source=&backing[..8*8*4];let copy=source.to_vec();let offset=&backing[4..];let mut actual=FloodRegionCursor::new(8,8,0,0).unwrap();let mut uninterrupted=FloodRegionCursor::new(8,8,0,0).unwrap();
 loop{let step=actual.advance(FloodSource::Rgba(source),3,GRANT,false).result.unwrap();let expected=uninterrupted.advance(FloodSource::Rgba(source),3,GRANT,false).result.unwrap();assert_eq!(step,expected);if step.completed>64{break;}}
 for refused in[copy.as_slice(),offset]{let(turn,heap)=observe(||actual.advance(FloodSource::Rgba(refused),3,GRANT,false));assert_eq!(heap,(0,0));assert_eq!(turn.work,0);let error=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.retained_progress(),RetainedCloneProgress::default());}
 let same_range=&backing[0..8*8*4];while !actual.done(){assert_eq!(actual.advance(FloodSource::Rgba(same_range),3,GRANT,false).result.unwrap(),uninterrupted.advance(FloodSource::Rgba(source),3,GRANT,false).result.unwrap());}assert_eq!(actual.result().unwrap(),uninterrupted.result().unwrap());close(&mut actual);close(&mut uninterrupted);
}

#[test]
fn large_workspace_cancellation_retires_under_mounted_release_grain(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("large-close.json")).unwrap();let width=fixture["width"].as_u64().unwrap()as u32;let height=fixture["height"].as_u64().unwrap()as u32;let mut cursor=FloodRegionCursor::new(width,height,0,0).unwrap();let mut retained=0;
 loop{let demand=cursor.demands(256).unwrap();let step=cursor.advance(FloodSource::Uniform([255;4]),256,GRANT,false).result.unwrap();assert!(step.progress.retained_capacity_bytes<=demand.capacity_bytes);retained+=step.progress.retained_capacity_bytes;if step.completed>0{break}}
 assert_eq!(retained,cursor.workspace_bytes());assert!(retained>GRANT.maximum_release_bytes);assert_eq!(cursor.advance(FloodSource::Uniform([255;4]),256,GRANT,true).result.unwrap_err().kind,ValueRefusalKind::Canceled);cursor.begin_close();let mut released=0;let bound=close_bound(&cursor);for _ in 0..bound{if cursor.terminal_is_empty(){break}let demand=cursor.close_demands(GRANT.maximum_copy_bytes).unwrap();assert!(demand.release_bytes<=GRANT.maximum_release_bytes);let turn=cursor.close_step(GRANT);assert!(turn.work>0);let progress=turn.result.unwrap().progress();assert!(progress.fits(GRANT));retained+=progress.retained_capacity_bytes;released+=progress.released_bytes;}assert!(cursor.terminal_is_empty());assert_eq!(released,retained);assert_eq!(cursor.workspace_bytes(),0);
}
#[test]
fn maximum_extent_directories_and_leaf_quotes_fit_mounted_release_grain(){let mut cursor=FloodRegionCursor::new(4096,4096,0,0).unwrap();for _ in 0..3{let demand=cursor.demands(256).unwrap();assert!(demand.capacity_bytes<=GRANT.maximum_release_bytes);cursor.advance(FloodSource::Uniform([255;4]),256,GRANT,false).result.unwrap();}assert_eq!(cursor.demands(256).unwrap().capacity_bytes,FLOOD_PAGE_PIXELS);close(&mut cursor);}

#[test]
fn neutral_non_square_paged_connectivity_and_allocation_prefixes(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("paged.json")).unwrap();let row=&fixture["cases"][0];let width=row["width"].as_u64().unwrap()as usize;let height=row["height"].as_u64().unwrap()as usize;let stride=row["whiteColumnStride"].as_u64().unwrap()as usize;let connector=row["connectorRow"].as_u64().unwrap()as usize;let count=width*height;let pages=count.div_ceil(FLOOD_PAGE_PIXELS);let source:Vec<u8>=(0..count).flat_map(|index|if index%width%stride==0||index/width==connector{[255;4]}else{[0,0,0,255]}).collect();let mut cursor=FloodRegionCursor::new(width as u32,height as u32,0,connector as u32).unwrap();let mut capacity=0;let budget=fixture["maximumWork"].as_u64().unwrap()as usize;
 while !cursor.done(){let quote=cursor.demands(budget).unwrap();let turn=cursor.advance(FloodSource::Rgba(&source),budget,GRANT,false);assert!(turn.work>0&&turn.work<=budget as u64);let step=turn.result.unwrap();assert!(step.progress.copied_bytes<=quote.copy_bytes&&step.progress.retained_capacity_bytes<=quote.capacity_bytes);capacity+=step.progress.retained_capacity_bytes;assert_eq!(cursor.workspace_bytes(),capacity);}
 assert_eq!(capacity,count*6+pages*3*size_of::<Vec<u8>>());assert_eq!(cursor.result().unwrap().iter().filter(|value|**value!=0).count(),row["expectedReached"].as_u64().unwrap()as usize);for index in 0..count{assert_eq!(cursor.result().unwrap().at(index).unwrap()!=0,index%width%stride==0||index/width==connector);}close(&mut cursor);
 for prefix in 0..=3+3*pages{let mut cursor=FloodRegionCursor::new(width as u32,height as u32,0,connector as u32).unwrap();let mut retained=0;for _ in 0..prefix{let step=cursor.advance(FloodSource::Rgba(&source),budget,GRANT,false).result.unwrap();retained+=step.progress.retained_capacity_bytes;assert_eq!(cursor.workspace_bytes(),retained);}assert_eq!(cursor.advance(FloodSource::Rgba(&source),budget,GRANT,true).result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(cursor.workspace_bytes(),retained);close(&mut cursor);}
}
